import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadNationalParksData(){const e=readFileSync(resolve(__dirname,"../../frontend/national-parks-explorer/data.js"),"utf-8");return new Function(e+"\nreturn { NATIONAL_PARKS, TIGER_RESERVES, UNESCO_SITES, WILDLIFE_SPECIES, STATES };")()}describe("National Parks Explorer — Data Integrity",()=>{let e;beforeAll(()=>{e=loadNationalParksData()}),it("NATIONAL_PARKS is a non-empty array",()=>{expect(Array.isArray(e.NATIONAL_PARKS)).toBe(!0),expect(e.NATIONAL_PARKS.length).toBeGreaterThan(0)}),it("every park has required fields",()=>{const t=["id","name","state","stateId","established","area","areaUnit","type","description","keyFauna","keyFlora","coordinates","climate","bestTime","entryFee","image"];e.NATIONAL_PARKS.forEach(e=>{t.forEach(t=>{expect(e).toHaveProperty(t)})})}),it("every park has a unique id",()=>{const t=e.NATIONAL_PARKS.map(e=>e.id);expect(new Set(t).size).toBe(t.length)}),it("every park has valid coordinates (lat 0-90, lng 0-180)",()=>{e.NATIONAL_PARKS.forEach(e=>{expect(e.coordinates.lat).toBeGreaterThanOrEqual(0),expect(e.coordinates.lat).toBeLessThanOrEqual(90),expect(e.coordinates.lng).toBeGreaterThanOrEqual(0),expect(e.coordinates.lng).toBeLessThanOrEqual(180)})}),it("keyFauna is a non-empty array of strings",()=>{e.NATIONAL_PARKS.forEach(e=>{expect(Array.isArray(e.keyFauna)).toBe(!0),expect(e.keyFauna.length).toBeGreaterThan(0),e.keyFauna.forEach(e=>expect(typeof e).toBe("string"))})}),it("keyFlora is a non-empty array of strings",()=>{e.NATIONAL_PARKS.forEach(e=>{expect(Array.isArray(e.keyFlora)).toBe(!0),expect(e.keyFlora.length).toBeGreaterThan(0),e.keyFlora.forEach(e=>expect(typeof e).toBe("string"))})}),it("image URLs start with https://",()=>{e.NATIONAL_PARKS.forEach(e=>{expect(e.image).toMatch(/^https:\/\//)})}),it("isTigerReserve and isUNESCO are booleans",()=>{e.NATIONAL_PARKS.forEach(e=>{expect(typeof e.isTigerReserve).toBe("boolean"),expect(typeof e.isUNESCO).toBe("boolean")})})}),describe("National Parks Explorer — Derived Data",()=>{let e;beforeAll(()=>{e=loadNationalParksData()}),it("TIGER_RESERVES contains only parks with isTigerReserve=true",()=>{expect(e.TIGER_RESERVES.length).toBeGreaterThan(0),e.TIGER_RESERVES.forEach(e=>{expect(e.isTigerReserve).toBe(!0)})}),it("UNESCO_SITES contains only parks with isUNESCO=true",()=>{expect(e.UNESCO_SITES.length).toBeGreaterThan(0),e.UNESCO_SITES.forEach(e=>{expect(e.isUNESCO).toBe(!0)})}),it("TIGER_RESERVES is a subset of NATIONAL_PARKS",()=>{const t=e.NATIONAL_PARKS.map(e=>e.id);e.TIGER_RESERVES.forEach(e=>{expect(t).toContain(e.id)})}),it("UNESCO_SITES is a subset of NATIONAL_PARKS",()=>{const t=e.NATIONAL_PARKS.map(e=>e.id);e.UNESCO_SITES.forEach(e=>{expect(t).toContain(e.id)})})}),describe("National Parks Explorer — Filter Logic",()=>{let e;function t(t){return e.NATIONAL_PARKS.filter(a=>{let r=!0;if(t.search){const e=t.search.toLowerCase();r=a.name.toLowerCase().includes(e)||a.state.toLowerCase().includes(e)||a.description.toLowerCase().includes(e)||a.keyFauna.some(t=>t.toLowerCase().includes(e))}const o="all"===t.state||a.state===t.state;let n=!0;"tiger"===t.type?n=a.isTigerReserve:"unesco"===t.type?n=a.isUNESCO:"national"===t.type?n=!a.isTigerReserve&&!a.isUNESCO&&!a.type.includes("Marine"):"marine"===t.type&&(n=a.type.includes("Marine"));let s=!0;if("all"!==t.region){const r=e.STATES.find(e=>e.name===a.state);s=r&&r.region===t.region}return r&&o&&n&&s})}beforeAll(()=>{e=loadNationalParksData()});const a={search:"",state:"all",type:"all",region:"all"};it("returns all parks with no filters",()=>{expect(t(a)).toHaveLength(e.NATIONAL_PARKS.length)}),it("filters by search term (name)",()=>{const e=t({...a,search:"Corbett"});expect(e.length).toBeGreaterThanOrEqual(1),expect(e[0].name).toContain("Corbett")}),it("filters by search term (state)",()=>{const e=t({...a,search:"Kerala"});expect(e.length).toBeGreaterThanOrEqual(1),e.forEach(e=>expect(e.state).toBe("Kerala"))}),it("filters by search term (fauna)",()=>{const e=t({...a,search:"Snow Leopard"});expect(e.length).toBeGreaterThanOrEqual(1),e.forEach(e=>{expect(e.keyFauna.some(e=>e.toLowerCase().includes("snow leopard"))).toBe(!0)})}),it("filters by tiger reserves only",()=>{const e=t({...a,type:"tiger"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.isTigerReserve).toBe(!0))}),it("filters by UNESCO sites only",()=>{const e=t({...a,type:"unesco"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.isUNESCO).toBe(!0))}),it("filters by marine parks only",()=>{const e=t({...a,type:"marine"});expect(e.length).toBeGreaterThanOrEqual(1),e.forEach(e=>expect(e.type).toContain("Marine"))}),it("filters by state",()=>{const e=t({...a,state:"Karnataka"});expect(e.length).toBeGreaterThanOrEqual(1),e.forEach(e=>expect(e.state).toBe("Karnataka"))}),it("filters by region",()=>{const r=t({...a,region:"south"});expect(r.length).toBeGreaterThan(0),r.forEach(t=>{const a=e.STATES.find(e=>e.name===t.state);expect(a&&a.region).toBe("south")})}),it("returns empty array for non-matching search",()=>{const e=t({...a,search:"xyznonexistent"});expect(e).toHaveLength(0)}),it("combines multiple filters",()=>{const e=t({search:"",state:"Rajasthan",type:"tiger",region:"all"});expect(e.length).toBeGreaterThanOrEqual(1),e.forEach(e=>{expect(e.state).toBe("Rajasthan"),expect(e.isTigerReserve).toBe(!0)})})}),describe("National Parks Explorer — Wildlife Species",()=>{let e;beforeAll(()=>{e=loadNationalParksData()}),it("WILDLIFE_SPECIES is a non-empty array",()=>{expect(Array.isArray(e.WILDLIFE_SPECIES)).toBe(!0),expect(e.WILDLIFE_SPECIES.length).toBeGreaterThan(0)}),it("every species has required fields",()=>{e.WILDLIFE_SPECIES.forEach(e=>{expect(e).toHaveProperty("name"),expect(e).toHaveProperty("status"),expect(e).toHaveProperty("image"),expect(e).toHaveProperty("description"),expect(e).toHaveProperty("parks"),expect(typeof e.name).toBe("string"),expect(typeof e.status).toBe("string"),expect(typeof e.image).toBe("string"),expect(typeof e.description).toBe("string"),expect(Array.isArray(e.parks)).toBe(!0)})}),it("every species references valid park IDs",()=>{const t=e.NATIONAL_PARKS.map(e=>e.id);e.WILDLIFE_SPECIES.forEach(e=>{e.parks.forEach(e=>{expect(t).toContain(e)})})}),it("species have valid conservation statuses",()=>{const t=["Least Concern","Near Threatened","Vulnerable","Endangered","Critically Endangered"];e.WILDLIFE_SPECIES.forEach(e=>{expect(t).toContain(e.status)})})}),describe("National Parks Explorer — States Data",()=>{let e;beforeAll(()=>{e=loadNationalParksData()}),it("STATES is a non-empty array",()=>{expect(Array.isArray(e.STATES)).toBe(!0),expect(e.STATES.length).toBeGreaterThan(0)}),it("every state has name and region",()=>{e.STATES.forEach(e=>{expect(e).toHaveProperty("name"),expect(e).toHaveProperty("region"),expect(typeof e.name).toBe("string"),expect(typeof e.region).toBe("string")})}),it("regions are from a valid set",()=>{const t=["all","north","south","east","west","central","northeast"];e.STATES.forEach(e=>{expect(t).toContain(e.region)})}),it("all park states have a matching entry in STATES",()=>{const t=e.STATES.map(e=>e.name);e.NATIONAL_PARKS.forEach(e=>{expect(t).toContain(e.state)})})});